package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.JdbcCatalogPreviousAnalysisOwnership;
import java.util.*;
import java.util.concurrent.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.*;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Actual scalar reads/locks, not a completed analysis or version qualification fixture. */
class CatalogPreviousAnalysisOwnershipTest {
    GenerationJdbcStoreTest f;JdbcCatalogPreviousAnalysisOwnership store;TransactionTemplate reads,writer;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){f=database();f.fixture();boolean h2=f.source instanceof org.h2.jdbcx.JdbcDataSource;f.jdbc.execute("DROP TABLE IF EXISTS analyzed_entities");f.jdbc.execute("DROP TABLE IF EXISTS contents");f.jdbc.execute("CREATE TABLE analyzed_entities(id VARCHAR(64) PRIMARY KEY,category VARCHAR(16),identity_key TEXT,identity_hash BINARY(32),revision BIGINT,analysis_generation BIGINT,analysis_state VARCHAR(32),legacy_flag INT)");f.jdbc.execute(h2?ResultJdbcStoreTest.CONTENT_DDL:ResultJdbcStoreTest.CONTENT_DDL.replace("CLOB","JSON").replace("TIMESTAMP","DATETIME(6)")+" ENGINE=InnoDB");store=new JdbcCatalogPreviousAnalysisOwnership(f.source);reads=new TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.source));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);writer=new TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.source));writer.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);}
    void insert(String category){f.jdbc.update("INSERT INTO analyzed_entities VALUES(?,?,?,?,0,0,'pending',0)","fictional-"+category,category,"fictional-identity",new byte[32]);f.jdbc.update("INSERT INTO contents(kind,id,natural_key,title,body_json,state,revision,body_revision,input_job_id,entity_id,body_hash_v1,updated_at) VALUES(?,?,?,?,?,'draft',1,1,?,?,?,?)",category,"fictional-content",category,"Fictional content","{\"fictional\":true}","fictional-prior-root","fictional-"+category,new byte[32],java.sql.Timestamp.from(f.clock.instant()));}
    @Test void FourClosedCategoriesReadExactKnownZeroAndScalarOwnerWithoutBodyJson(){
        for(String category:List.of("agent","skill","workflow","model")){insert(category);f.jdbc.update("UPDATE contents SET body_json=? WHERE kind=?","{\"fictional\":\""+"X".repeat(262145)+"\"}",category);reads.execute(s->{var entity=store.entity("fictional-"+category);var content=store.content(category,"fictional-content");assertEquals(category,entity.category());assertEquals(0,entity.revision());assertEquals(0,entity.generation());assertEquals(0,entity.legacy());assertEquals("pending",entity.state());assertEquals(entity.id(),content.entity());assertEquals("fictional-prior-root",content.inputRoot());assertEquals(1,content.bodyRevision());assertFalse(entity.toString().contains("fictional-"));assertFalse(content.toString().contains("fictional-"));return true;});}
    }
    @Test void UnknownLegacyNullMetadataIsPreservedAndForeignOrAbsentKeysNeverFallback(){
        insert("agent");f.jdbc.update("UPDATE analyzed_entities SET identity_key=NULL,identity_hash=NULL,revision=NULL,analysis_generation=NULL,analysis_state=NULL,legacy_flag=NULL");f.jdbc.update("UPDATE contents SET entity_id=NULL,input_job_id=NULL,body_hash_v1=NULL,body_revision=NULL");reads.execute(s->{var entity=store.entity("fictional-agent");assertNull(entity.identity());assertNull(entity.identityHash());assertNull(entity.revision());assertNull(entity.generation());assertNull(entity.state());assertNull(entity.legacy());assertNull(entity.identityBytes());var content=store.content("agent","fictional-content");assertNull(content.entity());assertNull(content.inputRoot());assertNull(content.bodyHash());assertNull(content.bodyRevision());assertNull(store.entity("fictional-absent"));assertNull(store.content("model","fictional-content"));assertThrows(RuntimeException.class,()->store.content("news_tech","fictional-content"));return true;});
    }
    @Test void NativeByteBoundsAreEnforcedBeforeReturningIdentityAndHashesAreDefensive(){
        insert("skill");f.jdbc.update("UPDATE analyzed_entities SET identity_key=?","界".repeat(1365)+"x");reads.execute(s->{var entity=store.entity("fictional-skill");assertEquals(4096,entity.identityBytes());var copy=entity.identityHash();copy[0]=1;assertEquals(0,entity.identityHash()[0]);var content=store.content("skill","fictional-content");var hash=content.bodyHash();hash[0]=1;assertEquals(0,content.bodyHash()[0]);return true;});f.jdbc.update("UPDATE analyzed_entities SET identity_key=?","界".repeat(1365)+"xx");assertThrows(RuntimeException.class,()->reads.execute(s->store.entity("fictional-skill")));f.jdbc.update("UPDATE analyzed_entities SET identity_key=''");assertThrows(RuntimeException.class,()->reads.execute(s->store.entity("fictional-skill")));
    }
    @Test void CallerMustUseReadonlyRepeatableSnapshotOrActualReadCommittedWriter(){
        insert("workflow");assertThrows(RuntimeException.class,()->store.entity("fictional-workflow"));assertThrows(RuntimeException.class,()->store.lockedEntity("fictional-workflow"));assertThrows(RuntimeException.class,()->writer.execute(s->store.entity("fictional-workflow")));assertThrows(RuntimeException.class,()->reads.execute(s->store.lockedEntity("fictional-workflow")));var wrong=new TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.source));wrong.setReadOnly(true);wrong.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->wrong.execute(s->store.entity("fictional-workflow")));writer.execute(s->{assertEquals("fictional-workflow",store.lockedEntity("fictional-workflow").id());assertEquals("fictional-workflow",store.lockedContent("workflow","fictional-content").entity());return true;});
    }
    @Test void ActualRepeatableSnapshotStaysStableAcrossIndependentWriterAndConstructorDoesNoIo()throws Exception{
        insert("model");try(var runner=Executors.newSingleThreadExecutor()){reads.execute(s->{assertEquals(0,store.entity("fictional-model").revision());try{runner.submit(()->f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1 WHERE id='fictional-model'")).get(5,TimeUnit.SECONDS);}catch(Exception failed){throw new IllegalStateException(failed);}assertEquals(0,store.entity("fictional-model").revision());return true;});}assertEquals(1,reads.execute(s->store.entity("fictional-model")).revision());var source=mock(DataSource.class);assertNotNull(new JdbcCatalogPreviousAnalysisOwnership(source));verifyNoInteractions(source);assertThrows(RuntimeException.class,()->new JdbcCatalogPreviousAnalysisOwnership(null));
    }
}
